-- CulinaLinkTX runtime-kernel reference migration. Apply only through an approved PostgreSQL migration process.
CREATE SCHEMA IF NOT EXISTS workflow;CREATE SCHEMA IF NOT EXISTS admin;CREATE SCHEMA IF NOT EXISTS integration;
CREATE TABLE IF NOT EXISTS workflow.runtime_runs(id uuid PRIMARY KEY,definition_id text NOT NULL,state text NOT NULL,status text NOT NULL,correlation_id text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,version bigint NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS workflow.runtime_events(id bigserial PRIMARY KEY,run_id uuid NOT NULL REFERENCES workflow.runtime_runs(id),event_type text NOT NULL,from_state text,to_state text,reason text,correlation_id text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workflow.runtime_tasks(id uuid PRIMARY KEY,run_id uuid REFERENCES workflow.runtime_runs(id),title text NOT NULL,status text NOT NULL,priority text NOT NULL,owner_id text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE IF NOT EXISTS admin.runtime_jobs(id uuid PRIMARY KEY,kind text NOT NULL,status text NOT NULL,attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),next_attempt_at timestamptz NOT NULL,correlation_id text,payload jsonb NOT NULL DEFAULT '{}'::jsonb,last_error text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE IF NOT EXISTS admin.runtime_dead_letters(id uuid PRIMARY KEY,job_id uuid NOT NULL,kind text NOT NULL,payload jsonb NOT NULL,last_error text,attempts integer NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin.runtime_reconciliation(id uuid PRIMARY KEY,job_id uuid,kind text NOT NULL,status text NOT NULL,reason text,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE INDEX IF NOT EXISTS runtime_runs_state_idx ON workflow.runtime_runs(state,status);CREATE INDEX IF NOT EXISTS runtime_tasks_status_idx ON workflow.runtime_tasks(status,priority);CREATE INDEX IF NOT EXISTS runtime_jobs_due_idx ON admin.runtime_jobs(status,next_attempt_at);